'use client';

/**
 * The world map.
 *
 * A map of the whole region, with every plot on it in its place. The land is
 * painted from the plots themselves — each one's territory takes the colour of
 * its biome — so the desert really is out west and the fen really is down by
 * the southern water, and choosing where to settle is a decision about a place
 * rather than a scroll through a list of cards.
 *
 * Selecting a plot brings up its real terrain, generated by the same code that
 * will run the world once it is claimed, so the ground shown is the ground you
 * get.
 *
 * Claims are shared. The relay holds one row per plot, so land another player
 * took is marked here as theirs and cannot be claimed a second time — and their
 * settlement can be visited from the marker. That registry is the server's
 * word, not this browser's; when the contract is deployed it becomes the
 * chain's, and nothing above this line changes.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { defaultWorldName } from '@/lib/simulation';
import {
  CHART_COUNT, HOME_CHART_INDEX, chartCapacity, chartName, chartRoom, claimOf, drawPlotPreview,
  drawRegionMap, inspectPlot, islandsFor, marketPlots,
  type ClaimedWorld, type PlayerRecord, type Plot,
} from '@/lib/world/plots';
import {
  ACTIVE_CHAIN, TOKEN, claimPlot, plotOwner, registryLive, shortAddress, tokenLive,
  type PlotOwnership,
} from '@/lib/chain/emerge';
import { EARNING_PLOT_LIMIT, LOCAL_TEST_ALLOCATION, PROSPECT_COST_EMERGE } from '@/lib/chain/vault';
import { spend } from '@/lib/chain/spend';
import { fetchClaims, surveyPlot, takePlot, type Claim, type Find } from '@/lib/net/registry';
import { WalletPicker, useWallet } from './WalletPicker';

/**
 * Ask the chain who owns a plot.
 *
 * Only answers once the registry contract exists. The shared relay below is
 * what actually keeps two players off the same land today; this is here so
 * that the moment the contract is deployed the chain's answer is the one shown.
 */
function useChainOwner(seed: number | null) {
  const [state, setState] = useState<PlotOwnership | null>(null);
  useEffect(() => {
    if (seed === null || !registryLive()) { setState(null); return; }
    let live = true;
    setState(null);
    plotOwner(seed).then((result) => { if (live) setState(result); });
    return () => { live = false; };
  }, [seed]);
  return state;
}

/** How often the map re-reads who owns what, in milliseconds. */
const CLAIMS_POLL = 12_000;

/**
 * Every claim anybody holds, kept fresh.
 *
 * Polled rather than pushed: land changes hands a few times an hour at most,
 * and a poll survives a serverless deployment where a socket does not.
 */
function useAllClaims() {
  const [claims, setClaims] = useState<Claim[]>([]);
  const [finds, setFinds] = useState<Find[]>([]);
  const [shared, setShared] = useState(true);
  useEffect(() => {
    let live = true;
    const tick = async () => {
      const result = await fetchClaims();
      if (!live) return;
      setClaims(result.claims);
      setFinds(result.finds);
      setShared(result.shared && !result.offline);
    };
    tick();
    const timer = window.setInterval(tick, CLAIMS_POLL);
    return () => { live = false; window.clearInterval(timer); };
  }, []);
  return { claims, finds, shared, setClaims, setFinds };
}

function PlotPreview({ seed }: { seed: number }) {
  const ref = useRef<HTMLCanvasElement | null>(null);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    // Generation takes a few tens of milliseconds; yielding a frame first keeps
    // the panel from appearing after a visible stall when the selection changes.
    const id = requestAnimationFrame(() => drawPlotPreview(canvas, seed));
    return () => cancelAnimationFrame(id);
  }, [seed]);
  return <canvas ref={ref} width={320} height={180} className="plot-canvas" />;
}

/**
 * The region.
 *
 * The canvas is painted once per set of plots and never re-rendered by React;
 * the markers are real buttons laid over it, so they can be tabbed to, focused
 * and read by a screen reader instead of being pixels with a hit test.
 */
function RegionMap({ plots, selected, chart, owned, taken, onSelect }: {
  plots: Plot[];
  selected: Plot | null;
  chart: number;
  /** Seeds this player holds, so their own land is marked on the map. */
  owned: Set<number>;
  /** Seeds somebody else holds, by seed, so their land is marked as theirs. */
  taken: Map<number, Claim>;
  onSelect: (plot: Plot) => void;
}) {
  const ref = useRef<HTMLCanvasElement | null>(null);
  useEffect(() => {
    if (ref.current) drawRegionMap(ref.current, plots, chart);
  }, [plots, chart]);

  return (
    <div className="region">
      <canvas ref={ref} width={900} height={570} className="region-canvas" aria-hidden />
      <div className="region-pins">
        {/* Every island is named, surveyed or not: an empty coast the player
            can see is what makes prospecting somewhere to go. */}
        {islandsFor(chart).map((island) => (
          <span
            key={island.name}
            className="island-name"
            // Below the island, where the markers are not.
            style={{ left: `${island.x * 100}%`, top: `${(island.y + island.ry * 0.92) * 100}%` }}
          >
            {island.name}
          </span>
        ))}
        {plots.map((plot) => {
          const mine = owned.has(plot.seed);
          const theirs = !mine ? taken.get(plot.seed) : undefined;
          return (
          <button
            key={plot.id}
            // A marker on the right-hand side of the map hangs its label to the
            // left, or it runs off the edge.
            className={`region-pin ${plot.biome} ${plot.mapX > 0.66 ? 'flip' : ''} ${plot.seed === selected?.seed ? 'selected' : ''} ${mine ? 'owned' : ''} ${theirs ? 'settled' : ''}`}
            style={{ left: `${plot.mapX * 100}%`, top: `${plot.mapY * 100}%` }}
            onClick={() => onSelect(plot)}
            aria-pressed={plot.seed === selected?.seed}
          >
            <span className="pin-dot" aria-hidden />
            <span className="pin-label">
              <b>
                {plot.region}
                {mine && <i className="yours">yours</i>}
                {theirs && <i className="settled-tag">settled</i>}
              </b>
              {/* The biome only on the one being looked at. Nine markers each
                  carrying two lines of text is more label than map. */}
              {plot.seed === selected?.seed && <em>{plot.biomeLabel}</em>}
            </span>
          </button>
          );
        })}
      </div>
      <div className="region-legend">
        <span>
          {plots.length} {plots.length === 1 ? 'plot' : 'plots'} surveyed on {islandsFor(chart).length} islands
        </span>
        <span>{plots.length ? 'Tap a marker to inspect the land' : 'Nothing here has been surveyed yet'}</span>
      </div>
    </div>
  );
}

export default function PlotSelect({ player, onPlayer, onEnter, onVisit }: {
  player: PlayerRecord;
  onPlayer: (record: PlayerRecord) => void;
  onEnter: (world: ClaimedWorld) => void;
  /** Go and look at somebody else's settlement. Resolves to a refusal, or null. */
  onVisit: (seed: number) => Promise<string | null>;
}) {
  const [chart, setChart] = useState(HOME_CHART_INDEX);
  const [selectedSeed, setSelectedSeed] = useState<number | null>(null);
  const [name, setName] = useState('');
  const { wallet } = useWallet();
  const [claiming, setClaiming] = useState(false);
  const [surveying, setSurveying] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  // On a phone the map and the claim panel cannot both be on screen, so the
  // panel becomes a sheet that the map opens.
  const [sheetOpen, setSheetOpen] = useState(false);
  const configured = tokenLive();

  const { claims: allClaims, finds, shared: registryShared, setClaims, setFinds } = useAllClaims();
  // Everybody's discoveries, in the shape the world model wants them.
  const discovered = useMemo(
    () => finds.map((f) => ({ seed: f.seed, chart: f.chart, slot: f.slot })),
    [finds],
  );
  const plots = useMemo(() => marketPlots(player, chart, discovered), [player, chart, discovered]);
  const room = useMemo(() => chartRoom(player, chart, discovered), [player, chart, discovered]);
  const selected: Plot | null = plots.find((p) => p.seed === selectedSeed) ?? plots[0] ?? null;
  const held = selected ? claimOf(player, selected.seed) : null;
  const registry = useChainOwner(selected?.seed ?? null);
  const ownedSeeds = useMemo(() => new Set(player.claims.map((c) => c.seed)), [player.claims]);
  const [visiting, setVisiting] = useState(false);

  /*
   * Who holds what, minus this player's own land.
   *
   * Compared by address, not by whether the seed appears in this browser's
   * record: a player who cleared their site data still owns their plots, and
   * should be shown them as theirs rather than as somebody else's.
   */
  const takenByOthers = useMemo(() => {
    const map = new Map<number, Claim>();
    for (const claim of allClaims) {
      const mine = wallet.address && claim.owner.toLowerCase() === wallet.address.toLowerCase();
      if (!mine) map.set(claim.seed, claim);
    }
    return map;
  }, [allClaims, wallet.address]);

  const heldByOther = selected ? takenByOthers.get(selected.seed) ?? null : null;

  const choose = useCallback((plot: Plot) => {
    setSelectedSeed(plot.seed);
    setSheetOpen(true);
  }, []);

  /**
   * Pay to find new land.
   *
   * The registry picks the berth, because it is the only party that can see
   * every plot already surveyed on this chart. A client choosing for itself
   * could only avoid the ones it knew about, so two players prospecting the
   * same chart took the same slot and put two settlements on one point of the
   * map — each invisible to the other. The fee is charged only after the
   * registry has actually handed over land.
   */
  const prospect = useCallback(async () => {
    if (!wallet.address) {
      setNotice('Connect a wallet first. Land you survey is recorded against your address.');
      return;
    }
    if (player.ledger.balance < PROSPECT_COST_EMERGE) {
      setNotice(`Prospecting costs ${PROSPECT_COST_EMERGE.toLocaleString()} ${TOKEN.ticker}.`);
      return;
    }
    setSurveying(true);
    setNotice(null);
    const result = await surveyPlot({
      chart,
      capacity: chartCapacity(chart),
      owner: wallet.address,
      ownerName: player.name,
    });
    setSurveying(false);
    if (!result.ok) {
      // Land is finite. When a chart is surveyed out the answer is to sail to
      // another one, not to stack another marker on the same skerry.
      setNotice(`${result.reason} Sail to another chart to find new land.`);
      return;
    }

    // Surveying burns its fee. Nothing the game charges is collected — and
    // with a token deployed the burn is a real transfer the player signs.
    const paid = await spend(player.ledger, PROSPECT_COST_EMERGE, wallet.address);
    if (!paid.ok) { setNotice(paid.refused); return; }
    const { find } = result;
    const found = inspectPlot(find.seed, find.slot, find.chart);
    setFinds((held) => [...held.filter((f) => f.seed !== find.seed), find]);
    onPlayer({
      ...player,
      ledger: paid.ledger,
      prospected: [...player.prospected, { seed: find.seed, chart: find.chart, slot: find.slot }],
    });
    setSelectedSeed(find.seed);
    setSheetOpen(true);
    setNotice(`Surveyed ${found.region} on ${found.island} — ${found.biomeLabel.toLowerCase()}. Everyone can see it now.`);
  }, [player, chart, onPlayer, wallet.address, setFinds]);

  const sail = useCallback((delta: number) => {
    setChart((c) => (c + delta + CHART_COUNT) % CHART_COUNT);
    setSelectedSeed(null);
    setSheetOpen(false);
    setNotice(null);
  }, []);

  /**
   * Take a plot.
   *
   * Three things have to be true, and the order matters. A wallet must be
   * connected, because a plot belongs to an address and everything the player
   * owns is keyed by it. The shared registry has to accept the claim — this is
   * what stops two people settling the same land, and a refusal here is final:
   * falling back to "claim it locally anyway" is exactly the bug this exists to
   * fix. Only then is the price charged, so a refused claim never costs
   * anything.
   */
  const claim = useCallback(async () => {
    if (!selected) return;
    const other = takenByOthers.get(selected.seed);
    // The registry outranks this browser's memory of what it owns.
    if (other) {
      setNotice(`${selected.region} already belongs to ${other.ownerName || shortAddress(other.owner)}.`);
      return;
    }
    // Already yours: this is the door back in, not a second purchase.
    const held = claimOf(player, selected.seed);
    if (held) { onEnter(held); return; }
    if (!wallet.address) {
      setNotice('Connect a wallet first. A plot belongs to an address, and so does everything you earn on it.');
      return;
    }
    if (player.ledger.balance < selected.price) {
      setNotice(`${selected.region} costs ${selected.price.toLocaleString()} ${TOKEN.ticker}.`);
      return;
    }

    setClaiming(true);
    setNotice(null);
    const worldName = name.trim() || defaultWorldName(selected.seed);

    const registered = await takePlot({
      seed: selected.seed,
      region: selected.region,
      worldName,
      owner: wallet.address,
      ownerName: player.name,
      price: selected.price,
    });
    if (!registered.ok) {
      setClaiming(false);
      setNotice(registered.reason);
      // Show the land as theirs straight away rather than making the player
      // wait for the next poll to understand why they were refused.
      if (registered.taken) setClaims((held2) => [...held2.filter((c) => c.seed !== registered.taken!.seed), registered.taken!]);
      return;
    }

    const result = await claimPlot({
      seed: selected.seed,
      region: selected.region,
      worldName,
      price: selected.price,
      address: wallet.address,
    });
    setClaiming(false);

    // Claiming costs what the plot is priced at, and the price is burned — it
    // used to cost nothing at all, the price being shown and never charged.
    const paid = await spend(player.ledger, selected.price, wallet.address);
    if (!paid.ok) {
      setNotice(paid.refused ?? `Not enough ${TOKEN.ticker} to claim ${selected.region}.`);
      return;
    }
    onPlayer({ ...player, ledger: paid.ledger });
    onEnter({
      seed: selected.seed,
      name: worldName,
      region: selected.region,
      price: selected.price,
      claimedAt: Date.now(),
      owner: wallet.address,
      txHash: result.txHash,
    });
  }, [name, selected, wallet.address, onEnter, onPlayer, player, takenByOthers, setClaims]);

  /** Go and look at the settlement somebody else built here. */
  const visit = useCallback(async (seed: number) => {
    setVisiting(true);
    setNotice(null);
    const refused = await onVisit(seed);
    setVisiting(false);
    if (refused) setNotice(refused);
  }, [onVisit]);

  const unlist = useCallback((seed: number) => {
    onPlayer({ ...player, listings: player.listings.filter((l) => l.seed !== seed) });
  }, [player, onPlayer]);


  return (
    <main className="world-map">
      <div className="land-inner">
        <header className="land-head">
          <div className="brand-line">
            <div className="brand-mark">✦</div>
            <div>
              <div className="wordmark">EMERGE</div>
              <div className="tagline">THE AI WORLD</div>
            </div>
          </div>
          <p className="land-intro">
            Every plot is a world waiting to happen, and no two are the same land. Claim one with
            {' '}{TOKEN.ticker}, give it a name, and the beings who live there will call it that.
          </p>
          <div className="land-head-side">
            <div className="land-balance">
              <span>YOUR BALANCE</span>
              <b>{Math.floor(player.ledger.balance).toLocaleString()}</b>
              <em>{TOKEN.ticker}</em>
            </div>
            <button
              className="ghost prospect"
              onClick={prospect}
              disabled={surveying || !wallet.address || player.ledger.balance < PROSPECT_COST_EMERGE || room.free === 0}
            >
              {surveying
                ? 'Surveying…'
                : room.free === 0
                  ? 'This chart is fully surveyed'
                  : !wallet.address
                    ? 'Connect a wallet to survey'
                    : `Prospect new land · ${PROSPECT_COST_EMERGE.toLocaleString()} ${TOKEN.ticker}`}
            </button>
          </div>
        </header>

        {/* Where in the world you are looking. Each chart holds a fixed number
            of plots; when it is full the only way to new land is to sail. */}
        <nav className="charts">
          <button className="ghost" onClick={() => sail(-1)} aria-label="Previous chart">‹</button>
          <div className="chart-name">
            <b>{chartName(chart)}</b>
            <em>
              {room.used} of {room.capacity} plots surveyed
              {room.free === 0 ? ' · nothing left to find here' : ` · room for ${room.free} more`}
            </em>
          </div>
          <button className="ghost" onClick={() => sail(1)} aria-label="Next chart">›</button>
        </nav>

        <div className="land-body">
          <RegionMap plots={plots} selected={selected} chart={chart} owned={ownedSeeds} taken={takenByOthers} onSelect={choose} />

          {!selected ? (
            <aside className="land-claim empty">
              <span className="eyebrow">UNSURVEYED</span>
              <h2>{chartName(chart)}</h2>
              <p className="muted">
                Nobody has set foot on these islands. There is room for {room.capacity} settlements out
                here; survey one to see what the land is made of.
              </p>
              <button
                className="claim-button"
                onClick={prospect}
                disabled={surveying || !wallet.address || player.ledger.balance < PROSPECT_COST_EMERGE}
              >
                {surveying
                  ? 'Surveying…'
                  : !wallet.address
                    ? 'Connect a wallet to survey'
                    : `Survey a plot · ${PROSPECT_COST_EMERGE.toLocaleString()} ${TOKEN.ticker}`}
              </button>
              {notice && <p className="warn">{notice}</p>}
            </aside>
          ) : (
          <aside className={`land-claim ${sheetOpen ? 'open' : ''}`}>
            <button className="sheet-close" onClick={() => setSheetOpen(false)} aria-label="Back to the map">×</button>
            {/* The registry decides, not this browser's memory. A stale local
                claim on land somebody else now holds must read as theirs. */}
            <span className="eyebrow">{heldByOther ? 'SETTLED' : held ? 'YOUR WORLD' : 'CLAIM'}</span>
            <h2>{heldByOther ? heldByOther.worldName : held ? held.name : selected.region}</h2>
            <div className="plot-traits">
              <span className={`biome-tag ${selected.biome}`}>{selected.biomeLabel}</span>
              <span>{selected.island}</span>
              <span>{selected.population} beings</span>
              {held && !heldByOther && <span className="owned-tag">Yours</span>}
              {heldByOther && <span className="settled-tag-big">Taken</span>}
            </div>
            {held && !heldByOther && (
              <p className="muted small">
                Claimed {new Date(held.claimedAt).toLocaleDateString()} for {held.price.toLocaleString()} {TOKEN.ticker}
                {held.owner ? ` by ${shortAddress(held.owner)}` : ' with no wallet connected'}.
                {held.txHash ? ` Settled on chain: ${held.txHash}.` : ' Recorded in this browser, not on chain.'}
              </p>
            )}
            {/* Who else holds this land. */}
            {heldByOther && (
              <div className="settled-by">
                <p className="muted small">
                  Settled by <b>{heldByOther.ownerName || shortAddress(heldByOther.owner)}</b>
                  {' '}on {new Date(heldByOther.at).toLocaleDateString()}, and called
                  {' '}<b>{heldByOther.worldName}</b>.
                </p>
                <button className="ghost" onClick={() => visit(heldByOther.seed)} disabled={visiting}>
                  {visiting ? 'Travelling…' : `Visit ${heldByOther.worldName}`}
                </button>
              </div>
            )}
            {registry?.onChain && registry.owner && !held && !heldByOther && (
              <p className="muted small">
                Held on {ACTIVE_CHAIN.label} by <b>{shortAddress(registry.owner)}</b>.
              </p>
            )}
            {!registryShared && !held && (
              <p className="muted small">
                This build has no shared registry behind it, so the only claims on this map are the ones
                made in this browser. Other players&rsquo; land will not show until one is configured.
              </p>
            )}

            <PlotPreview seed={selected.seed} />
            <p className="muted">{selected.blurb}</p>

            <span className="eyebrow">TRADES THIS LAND SUPPORTS</span>
            <div className="plot-traits">
              {selected.trades.map((t) => <span key={t}>{t}</span>)}
            </div>

            {!held && (
              <label className="name-field">
                <span>NAME YOUR WORLD</span>
                <input
                  value={name}
                  maxLength={24}
                  placeholder={defaultWorldName(selected.seed)}
                  onChange={(e) => setName(e.target.value)}
                />
              </label>
            )}

            <div className="claim-price">
              <span>{held ? 'PAID' : 'PRICE'}</span>
              <b>{selected.price.toLocaleString()}</b>
              <em>{TOKEN.ticker}</em>
            </div>

            <div className="claim-wallet"><WalletPicker compact /></div>

            <button
              className="claim-button"
              onClick={() => (heldByOther ? visit(heldByOther.seed) : claim())}
              disabled={
                claiming || visiting
                || (!held && !heldByOther && !wallet.address)
                || (!held && !heldByOther && player.ledger.balance < selected.price)
              }
            >
              {claiming
                ? 'Claiming…'
                : heldByOther
                  ? (visiting ? 'Travelling…' : `Visit ${heldByOther.worldName}`)
                  : held
                    ? `Enter ${held.name}`
                    : !wallet.address
                      ? 'Connect a wallet to claim land'
                      : player.ledger.balance < selected.price
                        ? `Not enough ${TOKEN.ticker}`
                        : `Claim ${selected.region} · ${selected.price.toLocaleString()} ${TOKEN.ticker}`}
            </button>
            {!wallet.address && !held && !heldByOther && (
              <p className="muted small">
                Your plots, your balance and your name all belong to a wallet address rather than to this
                browser, so there is nothing for a claim to belong to until one is connected.
              </p>
            )}

            {player.claims.length > 0 && (
              <>
                <span className="eyebrow">WORLDS YOU OWN</span>
                <div className="listing-list">
                  {[...player.claims].sort((a, b) => a.claimedAt - b.claimedAt).map((c, i) => (
                    <div key={c.seed} className={`listing-row ${c.seed === selected.seed ? 'here' : ''}`}>
                      <span>{c.name}{i >= EARNING_PLOT_LIMIT && <i className="idle-plot">not earning</i>}</span>
                      <b>{c.region}</b>
                      <button className="ghost" onClick={() => onEnter(c)}>Enter</button>
                    </div>
                  ))}
                </div>
                {player.claims.length > EARNING_PLOT_LIMIT && (
                  <p className="muted small">
                    The first {EARNING_PLOT_LIMIT} worlds you claimed earn {TOKEN.ticker}; the rest are
                    yours to play with. Give one up and the next in line starts earning.
                  </p>
                )}
              </>
            )}

            {player.listings.length > 0 && (
              <>
                <span className="eyebrow">YOUR LISTINGS</span>
                <div className="listing-list">
                  {player.listings.map((listing) => (
                    <div key={listing.seed} className="listing-row">
                      <span>{listing.region}</span>
                      <b>{listing.price.toLocaleString()} {TOKEN.ticker}</b>
                      <button className="ghost" onClick={() => unlist(listing.seed)}>Withdraw</button>
                    </div>
                  ))}
                </div>
                <p className="muted small">
                  Resale between players needs the plot registry on {ACTIVE_CHAIN.label}. Until it is
                  deployed a listing is recorded in this browser and no one else can see it.
                </p>
              </>
            )}

            {configured ? (
              <p className="muted small">
                Prices are real. Your balance is read from your wallet on {ACTIVE_CHAIN.label}, and
                claiming asks you to sign a transfer that destroys the {TOKEN.ticker} it costs.
                Ownership is recorded in the shared registry until the land contract is deployed,
                so a claim is enforced for every player but is not yet an on-chain title.
              </p>
            ) : (
              <p className="muted small">
                This build talks to {ACTIVE_CHAIN.label} (chain {ACTIVE_CHAIN.chainId}), but the
                {' '}{TOKEN.ticker} contract is not deployed there yet, so claims are recorded in the shared
                registry rather than on chain and you start with a local development allocation of
                {' '}{LOCAL_TEST_ALLOCATION.toLocaleString()} {TOKEN.ticker}. Neither is a token transfer.
              </p>
            )}
            {notice && <p className="warn">{notice}</p>}
          </aside>
          )}
        </div>
      </div>
    </main>
  );
}
